blocks.text:
/* 오른쪽으로 100 이동한 뒤 회전 */
transform: rotate(45deg) translateX(100px);

/* 회전한 뒤 그 방향으로 100 이동 — 결과가 다르다 */
transform: translateX(100px) rotate(45deg);

/* CSS 는 오른쪽 것이 먼저 적용된다 (안쪽부터) */

// canvas / CSS matrix(a, b, c, d, e, f)
// [ a c e ]
// [ b d f ]
// [ 0 0 1 ]

ctx.setTransform(1, 0, 0, 1, 0, 0);       // 항등 (아무것도 안 함)
ctx.setTransform(2, 0, 0, 2, 0, 0);       // 2배 확대
ctx.setTransform(cos, sin, -sin, cos, 0, 0);  // 회전

// e, f 가 이동. a,b,c,d 가 회전·크기·기울임
// 디버깅할 때 이 여섯 숫자를 찍어 보면 대개 원인이 보인다
